<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { NAlert, NButton, NInput, NInputNumber, NModal, useMessage } from 'naive-ui'
import { http } from '@/api/http'
interface Share { id: string; token: string; customPath?: string; enabled: boolean; fileId?: string; folderId?: string; downloadCount: number; maxDownloads?: number; expiresAt?: string; previewOnly: boolean; kind: string; passwordProtected?: boolean; allowedIps?: string[] }
const items = ref<Share[]>([])
const editing = ref<Share | null>(null)
const error = ref('')
const message = useMessage()
const password = ref('')
const removePassword = ref(false)
const clearExpiration = ref(false)
const clearLimit = ref(false)
const ips = ref('')
function edit(item: Share) { editing.value = { ...item }; password.value = ''; removePassword.value = false; clearExpiration.value = false; clearLimit.value = false; ips.value = (item.allowedIps ?? []).join('\n') }
async function load() { try { const [files, folders] = await Promise.all([http.get<{ items: Share[] }>('/shares'), http.get<{ items: Share[] }>('/folder-shares')]); items.value = [...files.items.map(i => ({ ...i, kind: 's' })), ...folders.items.map(i => ({ ...i, kind: 'fs' }))] } catch (e) { error.value = String(e) } }
async function disable(item: Share) { try { await http.delete(`/${item.kind === 's' ? 'shares' : 'folder-shares'}/${item.id}`); await load() } catch (e) { message.error(String(e)) } }
async function save() { const item = editing.value; if (!item) return; try { await http.patch(`/${item.kind === 's' ? 'shares' : 'folder-shares'}/${item.id}`, { enabled: item.enabled, previewOnly: item.previewOnly, maxDownloads: clearLimit.value ? undefined : item.maxDownloads, expiresAt: clearExpiration.value ? undefined : item.expiresAt || undefined, password: !removePassword.value && password.value ? password.value : undefined, removePassword: removePassword.value, clearExpiration: clearExpiration.value, clearDownloadLimit: clearLimit.value, allowedIps: ips.value.split(/[\s,]+/).filter(Boolean) }); editing.value = null; password.value = ''; await load() } catch (e) { message.error(String(e)) } }
onMounted(load)
</script>
<template><section class="module-page"><div class="module-heading"><div><div class="eyebrow">CONTROLLED DISTRIBUTION</div><h1>分享管理</h1><p>每一个对外入口，都有边界。请在文件详情中创建分享。</p></div><n-button @click="load">刷新分享</n-button></div><n-alert v-if="error" type="error">{{ error }}</n-alert><div v-if="!items.length" class="card empty-state">暂无分享，前往文件空间选择文件。</div><div class="resource-grid"><article v-for="item in items" :key="item.id" class="card"><div class="card-head"><span class="badge">{{ item.kind === 's' ? '文件' : '目录' }}</span><span class="badge">{{ item.enabled ? '生效中' : '已停用' }}</span></div><h2 class="break-word">{{ item.customPath || item.token }}</h2><p class="muted">{{ item.expiresAt || '不限有效期' }} · {{ item.previewOnly ? '仅预览' : '允许下载' }}</p><div class="resource-metrics"><span><strong>{{ item.downloadCount }}</strong>累计下载</span><span><strong>{{ item.maxDownloads ?? '不限' }}</strong>下载上限</span></div><div class="resource-actions"><a class="btn btn-secondary" :href="`/${item.kind}/${item.customPath || item.token}`" target="_blank" rel="noopener">访问分享</a><n-button @click="edit(item)">编辑规则</n-button><n-button quaternary type="error" :disabled="!item.enabled" @click="disable(item)">停用分享</n-button></div></article></div><n-modal :show="!!editing" preset="card" title="分享规则" class="module-dialog" @update:show="editing = null"><form v-if="editing" class="module-form" @submit.prevent="save"><label><input v-model="editing.enabled" type="checkbox" />启用分享</label><label><input v-model="editing.previewOnly" type="checkbox" />仅预览</label><label>下载次数上限<n-input-number v-model:value="editing.maxDownloads" :min="1" /></label><label>失效时间（ISO 8601）<n-input v-model:value="editing.expiresAt" placeholder="2027-01-01T00:00:00+08:00" /></label><label><input v-model="clearLimit" type="checkbox" aria-label="不限下载次数" />不限下载次数</label><label><input v-model="clearExpiration" type="checkbox" aria-label="清除失效时间" />清除失效时间</label><p class="muted">{{ editing.passwordProtected ? '当前已设置密码，留空不修改。' : '当前无需密码。' }}</p><label>新访问密码<n-input v-model:value="password" type="password" :disabled="removePassword" :input-props="{ 'aria-label': '新分享密码', maxlength: 72, autocomplete: 'new-password' }" /></label><label><input v-model="removePassword" type="checkbox" aria-label="移除访问密码" />移除访问密码</label><label>IP 白名单（每行一个 IP 或 CIDR，留空允许全部）<n-input v-model:value="ips" type="textarea" :input-props="{ 'aria-label': '分享 IP 白名单' }" /></label><n-button type="primary" attr-type="submit">保存规则</n-button></form></n-modal></section></template>
